llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Menaquinone-4, a naphthoquinone with a tetraprenyl side chain and the closest structural analogue (Morgan 0.6591), had absolute oral bioavailability of only 13.5% in dogs after soft-capsule administration, directly supporting F < 20% for the query's quinone-polyprenyl scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tocotrienol, a chromanol with a polyprenyl side chain, showed poor oral bioavailability in humans, supporting low F for the highly lipophilic polyprenyl query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Lycopene, a highly lipophilic C40 isoprenoid, showed very low systemic availability in humans (0.17% to ~2.6% in several studies), supporting low F for large lipophilic isoprenoid-type molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "MitoQ, a quinone-based lipophilic compound, had oral availability of only 10%, supporting low F for the query's quinone with a long lipophilic tail.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Phytoene, the closest carotenoid analogue, showed 58.5% absolute bioavailability in humans, which would argue for high F, but its lack of the polar quinone head and different absorption behavior reduce transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Hyperforin, a lipophilic prenylated natural product, showed high oral bioavailability in volunteers, providing a weak contradictory signal, but its much lower structural similarity and smaller size limit transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C31"],
      "claim": "Salirasib, a farnesyl thiosalicylate, showed 69.5% oral bioavailability in a preclinical CMC suspension, a contradictory high-F signal, but the absence of a quinone and lower similarity limit its relevance.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is CoQ10, an extremely lipophilic polyprenyl benzoquinone. The most transferable evidence—menaquinone-4 absolute bioavailability of 13.5% in dogs, MitoQ oral availability of 10%, tocotrienol poor human bioavailability, and lycopene low systemic availability—consistently supports F < 20%. The high-F signals from phytoene, hyperforin, and salirasib are less structurally relevant and do not overcome the quinone-polyprenyl absorption liabilities.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for CoQ10 itself in humans.",
    "Menaquinone-4 data are from dogs and a soft-capsule formulation; human CoQ10 may differ.",
    "Formulation effects are not captured; special formulations can improve absorption of lipophilic quinones.",
    "Carotenoid high-F data (phytoene) create uncertainty about whether long isoprenoid chains alone preclude absorption."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C37", "C35", "C29"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "menaquinone-4"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C27"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "mitoquinone"
    },
    {
      "applicability": "low",
      "card_ids": ["C31", "C38"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "salirasib"
    },
    {
      "applicability": "low",
      "card_ids": ["C33", "C28", "C34", "C30", "C36"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "mycophenolic acid"
    },
    {
      "applicability": "low",
      "card_ids": ["C32"],
      "decision_effect": "no_change",
      "direction": "neutral_or_unclear",
      "family": "fusidic acid"
    }
  ],
  "revision_action": "strengthen"
}

